-- The people working alongside the founder, and the photos that go with them.
--
-- Photos are stored in the row rather than in object storage. This site has no
-- R2 bucket and Pages Functions cannot write to the static asset store, so a
-- BLOB here is what makes an upload button possible at all without new
-- infrastructure. It suits the scale: a handful of head-and-shoulders portraits
-- at roughly 8KB each. If the team ever runs to dozens of people, or the photos
-- get large, move them to R2 and keep this column for the reference.
--
-- `sort_order` decides the running order on the page; ties fall back to name.
-- `status` keeps a half-written profile off the site without deleting it.
CREATE TABLE IF NOT EXISTS team_members (
  id               TEXT PRIMARY KEY,
  name             TEXT NOT NULL,
  role             TEXT NOT NULL DEFAULT '',
  bio              TEXT NOT NULL DEFAULT '',
  linkedin_url     TEXT NOT NULL DEFAULT '',
  photo            BLOB,
  photo_type       TEXT,                            -- image/webp|image/jpeg|image/png
  photo_updated_at TEXT,                            -- drives the photo cache key
  status           TEXT NOT NULL DEFAULT 'published', -- draft|published
  sort_order       INTEGER NOT NULL DEFAULT 0,
  created_at       TEXT NOT NULL,
  updated_at       TEXT
);

CREATE INDEX IF NOT EXISTS idx_team_visible
  ON team_members(status, sort_order, name);

-- First team member. The photo is embedded as a hex literal so a freshly
-- migrated database looks exactly like production without a second step; it is
-- the 320x320 WebP crop of the supplied portrait, about 8KB.
